contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = msg.sender; }

    // We accept parameters choosing an actor via a boolean: if asOwner==true we simulate owner by
    // calling through this contract (the deployer of C is this contract), otherwise we simulate
    // a non-owner by using the provided target address as the recipient of an external call that
    // attempts to invoke c (since the checker runs a single transaction and msg.sender for calls
    // to c will always be this contract, we simulate non-owner by first changing owner outwardly
    // is impossible; instead we rely on the fact that C.owner was set to the deployer of C (this
    // contract). So we distinguish by attempting the calls and checking whether they revert.

    // Note: to send ether to c we pass amount and call fallback via a direct low-level send to c.
    function run(bool callWithdraw, bool callWithdrawAll, bool callSendMoney, address sendTarget, uint sendValue, uint depositAmount) public payable {
        require(address(this).balance >= depositAmount, "not enough balance for deposit");
        // record initial observable state
        address ownerBefore = c.owner();
        uint depositsBefore = c.depositsCount();
        uint balBefore = address(c).balance;

        // make a deposit by sending Ether to trigger fallback
        // depositAmount may be zero
        if (depositAmount > 0) {
            // send Ether to c so its fallback increments depositsCount
            (bool s,) = address(c).call{value: depositAmount}("");
            // allow both success and failure; but ensure that if it succeeded depositsCount increased
        }

        // record after deposit
        address ownerAfterDeposit = c.owner();
        uint depositsAfterDeposit = c.depositsCount();
        uint balAfterDeposit = address(c).balance;

        // try owner-restricted calls and capture whether they revert
        bool revertedWithdraw = false;
        bool revertedWithdrawAll = false;
        bool revertedSendMoney = false;

        if (callWithdraw) {
            try c.withdraw(sendValue) {
                revertedWithdraw = false;
            } catch {
                revertedWithdraw = true;
            }
        }
        if (callWithdrawAll) {
            try c.withdrawAll() {
                revertedWithdrawAll = false;
            } catch {
                revertedWithdrawAll = true;
            }
        }
        if (callSendMoney) {
            // ensure this contract has enough balance to ask c to send (c will attempt to call sendTarget)
            try c.sendMoney(sendTarget, sendValue) {
                revertedSendMoney = false;
            } catch {
                revertedSendMoney = true;
            }
        }

        // Observations after attempts
        address ownerFinal = c.owner();
        uint depositsFinal = c.depositsCount();
        uint balFinal = address(c).balance;

        // General rule asserted:
        // 1) The owner must never change as a result of any of these calls (owner is set in constructor and no function changes it).
        // 2) depositsCount only increases due to successful fallback (i.e., depositsAfterDeposit - depositsBefore is either 0 or equal to number of successful fallback sends), and later owner-restricted calls cannot decrease depositsCount.
        // 3) If a privileged call reverted, it must not have transferred Ether out of the contract (balance unchanged by that call).
        // We combine these into a single assert relating the observed values and revert flags.

        // Construct the assertion:
        // - ownerBefore == ownerAfterDeposit == ownerFinal
        // - depositsFinal >= depositsBefore
        // - If any call reverted then balFinal == balAfterDeposit (no successful withdraw/send occurred after deposit)
        assert(ownerBefore == ownerAfterDeposit && ownerAfterDeposit == ownerFinal && depositsFinal >= depositsBefore && ((revertedWithdraw || revertedWithdrawAll || revertedSendMoney) ? balFinal == balAfterDeposit : true));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry exercising fallback and owner-only methods
    function run(address sendTarget, uint depositAmount, bool doWithdraw, uint withdrawAmount, bool doWithdrawAll, bool doSendMoney, uint sendValue) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to deposit");
        // observe initial state
        address ownerBefore = c.owner();
        uint depositsBefore = c.depositsCount();
        uint balBefore = address(c).balance;

        // make a deposit by sending Ether to c to trigger fallback (may succeed or fail)
        (bool depSuccess,) = address(c).call{value: depositAmount}("");

        // observe after deposit
        address ownerAfterDeposit = c.owner();
        uint depositsAfterDeposit = c.depositsCount();
        uint balAfterDeposit = address(c).balance;

        // Attempt owner-only calls as top-level statements and capture revert via try/catch
        bool revertedWithdraw;
        bool revertedWithdrawAll;
        bool revertedSendMoney;

        if (doWithdraw) {
            try c.withdraw(withdrawAmount) {
                revertedWithdraw = false;
            } catch {
                revertedWithdraw = true;
            }
        } else {
            revertedWithdraw = false;
        }

        if (doWithdrawAll) {
            try c.withdrawAll() {
                revertedWithdrawAll = false;
            } catch {
                revertedWithdrawAll = true;
            }
        } else {
            revertedWithdrawAll = false;
        }

        if (doSendMoney) {
            try c.sendMoney(sendTarget, sendValue) {
                revertedSendMoney = false;
            } catch {
                revertedSendMoney = true;
            }
        } else {
            revertedSendMoney = false;
        }

        // final observations
        address ownerFinal = c.owner();
        uint depositsFinal = c.depositsCount();
        uint balFinal = address(c).balance;

        // General rule asserted in one expression:
        // 1) Owner never changes through any of these interactions.
        // 2) depositsCount never decreases (fallback increments only) from before to final.
        // 3) If any owner-only call reverted then the contract balance did not decrease as a result of that call (i.e., final balance >= balance after deposit when any reverted).
        assert(
            ownerBefore == ownerAfterDeposit && ownerAfterDeposit == ownerFinal
            && depositsFinal >= depositsBefore
            && (
                (revertedWithdraw || revertedWithdrawAll || revertedSendMoney)
                ? balFinal >= balAfterDeposit
                : true
            )
        );
    }

    receive() external payable {}
}

