contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test permissioning and balance changes for withdraw, withdrawAll, and sendMoney.
    // Inputs:
    // - callerIsOwner: if true, this contract will behave as owner when calling C; otherwise calls should revert.
    // - sendAmount: amount of wei to attempt to send/withdraw from C (bounded by address(c).balance observable pre-call).
    // - action: 0 = withdraw, 1 = sendMoney, 2 = withdrawAll (ignores sendAmount for withdrawAll).
    function run(bool callerIsOwner, uint sendAmount, uint8 action) public payable {
        require(action <= 2);

        // Ensure this test contract has enough balance to fund any payable fallback if needed by deploying context.
        // We will first deposit some Ether into c by triggering its fallback. Use a parameter-derived amount to send in.
        uint deposit = msg.value; // amount provided by caller when invoking this test
        // deposit into c to create non-zero balance that owner may withdraw later
        if (deposit > 0) {
            // send deposit to c's fallback
            address(c).call{value: deposit}("");
        }

        // record observable pre-state
        uint balanceBefore = address(c).balance;
        uint depositsCountBefore = c.depositsCount();
        address owner = c.owner();

        // Determine whether this contract is owner: when C was deployed, owner was payable(msg.sender) at that time.
        // The checker deploys a fresh C and passes it to our constructor; thus our contract (InvMutTest) is the deployer
        // and is the owner. However the parameter callerIsOwner lets us simulate calls that should either succeed
        // (when callerIsOwner==true and we call functions directly) or fail (when callerIsOwner==false we attempt
        // to have a non-owner call via a low-level call from an externally owned account — not possible here).
        // To simulate non-owner calls, we require that callerIsOwner==true when this contract is actually the owner,
        // otherwise we will provoke a revert by calling through a crafted call where msg.sender != owner is impossible
        // in this environment. So instead, we check the general property as: if the caller equals owner then calls
        // that transfer out succeed and reduce balance; if caller != owner then such calls revert. We can observe this
        // by branching based on comparing owner to address(this).

        bool amOwner = (owner == address(this));

        // perform the action and observe whether it reverts
        bool reverted = false;
        if (action == 0) {
            // withdraw(sendAmount)
            try c.withdraw(sendAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (action == 1) {
            // sendMoney(target, sendAmount) - use address(this) as target to receive money back if allowed
            try c.sendMoney(address(this), sendAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // withdrawAll()
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint balanceAfter = address(c).balance;
        uint depositsCountAfter = c.depositsCount();

        // General rule asserted:
        // - If this contract is the owner (amOwner == true) then calls should NOT revert and the contract balance must not increase;
        //   moreover when a withdraw or sendMoney succeeds the contract balance must be <= before (i.e., not increased), and
        //   for withdrawAll when succeeded the balanceAfter must be 0.
        // - If this contract is NOT the owner then such calls must revert and thus balance and depositsCount remain unchanged.
        assert(
            (
                amOwner
                ? (
                    // owner: call should not revert
                    reverted == false
                    // balance didn't increase
                    && balanceAfter <= balanceBefore
                    // depositsCount only changes if fallback was invoked earlier; ensure no unexpected change due to these ops
                    && depositsCountAfter == depositsCountBefore
                    // withdrawAll when successful empties contract
                    && (action == 2 ? balanceAfter == 0 : true)
                )
                : (
                    // non-owner: call must revert and state unchanged
                    reverted == true
                    && balanceAfter == balanceBefore
                    && depositsCountAfter == depositsCountBefore
                )
            )
        );
    }

    // allow receiving Ether when c.sendMoney sends to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that invoking C's fallback increases depositsCount exactly by 1 and increases address(c).balance by the amount sent,
    // and that calling owner-only functions withdraw, withdrawAll, or sendMoney (when they succeed or revert) never increases depositsCount.
    // Parameters:
    // - deposit: amount of wei to send to c's fallback (must be funded by this contract beforehand)
    // - callAction: 0 = just fallback deposit; 1 = deposit then try withdraw(deposit); 2 = deposit then try sendMoney(address(this), deposit); 3 = deposit then try withdrawAll()
    function run(uint deposit, uint8 callAction) public payable {
        require(callAction <= 3);
        // ensure this contract has the funds to send deposit
        require(address(this).balance >= deposit);

        // initial observables
        uint balanceBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        // 1) invoke fallback by sending Ether to c
        (bool okDeposit, ) = address(c).call{value: deposit}("");
        // deposit may succeed or (in theory) revert; capture outcome
        bool depositReverted = !okDeposit;

        // read after-deposit observables
        uint balanceAfterDeposit = address(c).balance;
        uint depositsAfterDeposit = c.depositsCount();

        // 2) optionally perform one of the owner-only actions to ensure they do not further increment depositsCount
        bool actionReverted = false;
        if (callAction == 1) {
            try c.withdraw(deposit) {
                actionReverted = false;
            } catch {
                actionReverted = true;
            }
        } else if (callAction == 2) {
            try c.sendMoney(address(this), deposit) {
                actionReverted = false;
            } catch {
                actionReverted = true;
            }
        } else if (callAction == 3) {
            try c.withdrawAll() {
                actionReverted = false;
            } catch {
                actionReverted = true;
            }
        }

        uint depositsFinal = c.depositsCount();
        uint balanceFinal = address(c).balance;

        // Assertion (single general rule):
        // - If the deposit call succeeded, then depositsCount increased by exactly 1 and the contract balance increased by exactly deposit.
        // - Whether or not one of the owner-only actions was attempted afterwards, depositsCount must not increase further (i.e., final == afterDeposit),
        //   and the only allowed changes to balance after deposit are non-negative (withdraws may reduce it), but depositsCount never increments.
        assert(
            (
                // deposit succeeded: exactly +1 and balance increased by deposit
                (!depositReverted)
                && depositsAfterDeposit == depositsBefore + 1
                && balanceAfterDeposit == balanceBefore + deposit
                // no further increments from subsequent actions
                && depositsFinal == depositsAfterDeposit
            )
            ||
            (
                // deposit reverted: then nothing observable should have changed (balance and deposits unchanged), and final equals before
                (depositReverted
                    && depositsAfterDeposit == depositsBefore
                    && balanceAfterDeposit == balanceBefore
                    && depositsFinal == depositsBefore
                    && balanceFinal == balanceBefore)
            )
        );
    }

    // allow receiving Ether if c sends to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test that a single low-level Ether send (triggering fallback) is atomic with respect to depositsCount and balance:
    // - If the send succeeds, depositsCount increases by exactly 1 and address(c).balance increases by the sent amount.
    // - If the send reverts, depositsCount and balance remain exactly as before.
    // Parameters:
    // - amount: wei to send to c (this contract must have at least `amount` balance)
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // observe before-values through public surface
        uint balanceBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        // perform the low-level call that should trigger fallback()
        (bool ok, ) = address(c).call{value: amount}("");
        bool succeeded = ok;

        // observe after-values
        uint balanceAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();

        // Single assert expressing the general invariant for all inputs
        assert(
            (succeeded && depositsAfter == depositsBefore + 1 && balanceAfter == balanceBefore + amount)
            || (!succeeded && depositsAfter == depositsBefore && balanceAfter == balanceBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Send `amount` wei to c via a direct call (which will trigger C.fallback)
    // The test observes depositsCount and balance before and after and asserts
    // the atomic relation between success, depositsCount, and balance.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // observe before-values through public surface
        uint balanceBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        // perform the low-level call that should trigger fallback()
        bool succeeded;
        (succeeded, ) = address(c).call{value: amount}("");

        // observe after-values
        uint balanceAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();

        // General rule: either the call succeeded and depositsCount increased by 1 and balance increased by amount,
        // or it failed and both remained exactly the same.
        assert(
            (succeeded && depositsAfter == depositsBefore + 1 && balanceAfter == balanceBefore + amount)
            || (!succeeded && depositsAfter == depositsBefore && balanceAfter == balanceBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call C's fallback by invoking it directly as an external payable function on c.
    // We take amount as parameter and must have funds in this contract to forward.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // observe before-values through public surface
        uint balanceBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        // perform the call to the fallback as a top-level state-changing call on c
        bool succeeded;
        try c.fallback{value: amount}() {
            succeeded = true;
        } catch {
            succeeded = false;
        }

        // observe after-values
        uint balanceAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();

        // General rule: either the call succeeded and depositsCount increased by 1 and balance increased by amount,
        // or it failed and both remained exactly the same.
        assert(
            (succeeded && depositsAfter == depositsBefore + 1 && balanceAfter == balanceBefore + amount)
            || (!succeeded && depositsAfter == depositsBefore && balanceAfter == balanceBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will try actions as a non-owner (this contract) and verify they revert,
    // and also exercise fallback by sending Ether to c to increment depositsCount.
    // Inputs:
    // - sendAmount: amount of wei to send into c via fallback
    // - callAmount: amount to attempt to withdraw/send (used for withdraw/sendMoney)
    function run(uint sendAmount, uint callAmount, address payable target) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance for send");

        // Record depositsCount before sending to fallback
        uint beforeDeposits = c.depositsCount();

        // Send Ether to c to trigger fallback (empty calldata). This call will increase depositsCount.
        // Must be a top-level statement that changes c's state.
        (bool s1, ) = address(c).call{value: sendAmount}("");
        // s1 may be true if fallback accepted Ether, or false if it reverted.

        uint afterDeposits = c.depositsCount();

        // Try withdrawAll as non-owner (this contract is NOT the original deployer of C).
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        // Try withdraw as non-owner
        bool withdrewReverted;
        try c.withdraw(callAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Try sendMoney as non-owner
        bool sendMoneyReverted;
        try c.sendMoney(target, callAmount) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // General rule asserted for all inputs: if this contract is not the owner then withdraw/withdrawAll/sendMoney must revert;
        // and sending Ether with empty calldata either reverts (s1==false) or increments depositsCount by exactly 1.
        // We cannot directly read owner, but we know owner was set to the deployer of C (not this contract), so accesses from this contract should revert.
        // The assert encodes these properties using observable values.
        assert(
            // At least one of the state-change outcomes for fallback: either the call reverted (s1==false) OR depositsCount increased by exactly 1
            (s1 == false || afterDeposits == beforeDeposits + 1)
            // And all privileged functions called by this contract must have reverted
            && withdrewAllReverted && withdrewReverted && sendMoneyReverted
        );
    }

    // Allow this test contract to receive ETH so it can forward to c
    receive() external payable {}
}

