    // Inputs:
    // - sendAmount: wei to send to c with empty calldata to trigger fallback
    // - callAmount: amount passed to withdraw/sendMoney
    // - target: address passed to sendMoney
    function run(uint sendAmount, uint callAmount, address payable target) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance for send");

        // Read observable state before
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Trigger fallback by sending Ether with empty calldata (must be a top-level state-changing action)
        (bool sendOk, ) = address(c).call{value: sendAmount}("");

        // Attempt privileged calls as this contract (should revert because owner is deployer of C)
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

