    // - tryWithdrawValue: value to attempt to withdraw (via withdraw) after the deposit
    // The function is payable to allow funding this contract beforehand; we require this contract has at least `amount`.
    function run(uint256 amount, uint256 tryWithdrawValue) public payable {
