        uint256 afterDeposits = c.depositsCount();
        uint256 afterBalance = address(c).balance;
        address afterOwner = c.owner();

        // Now attempt to call withdraw(tryWithdrawValue) as this contract (which is NOT the original C owner).
        bool withdrewReverted;
        try c.withdraw(tryWithdrawValue) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

