        // 2) Additionally, since this InvMutTest contract is not the original owner (the owner was set when C was deployed by the harness), any attempt to call withdraw by this contract must either revert or not decrease address(c).balance. We express that as: if withdraw did not revert, then afterBalance <= beforeBalance + amount (i.e., withdraw did not extract more than available); and if withdraw reverted, balance unchanged by withdraw attempt.

        assert(
            // part 1: successful fallback call implies precise increment
            (okSend == false || (afterDeposits == beforeDeposits + 1 && afterBalance == beforeBalance + amount && afterOwner == beforeOwner))
            // part 2: withdraw attempt cannot reduce c's balance below the deposited amount boundary
            && (
                (withdrewReverted && address(c).balance == afterBalance)
                || (!withdrewReverted && address(c).balance <= beforeBalance + amount)
            )
        );
    }

    receive() external payable { }
}

