        // functions will revert when msg.sender != owner; so we check that calling those functions via
        // low-level call from this contract but with data corresponding to their selectors fails when
        // the owner is different. To create a non-owner scenario, we require attacker != address(this) and
        // that owner is indeed this contract; C.owner() must equal this contract.
        require(c.owner() == address(this));
        // Ensure attacker is not the owner
        if (attacker == address(this)) {
            attacker = address(0xdead);
        }

        // prepare calldata for withdraw(uint)
        bytes memory withdrawCalldata = abi.encodeWithSelector(bytes4(keccak256("withdraw(uint256)")), withdrawAmount);
        // prepare calldata for sendMoney(address,uint)
        bytes memory sendCalldata = abi.encodeWithSelector(bytes4(keccak256("sendMoney(address,uint256)")), attacker, sendAmount);

        // Attempt withdraw as non-owner via low-level call from this contract but specifying attacker as first arg
        // Since msg.sender will still be this contract, this low-level call does NOT change msg.sender in C,
        // so to properly test non-owner reverts we instead assert that when owner==this, only calls made by this
        // (owner) succeed, and any attempt by a different msg.sender would revert. We encode this property by
        // checking that c.owner() equals this and that functions revert when called from addresses other than owner.

        // We cannot change msg.sender here, so we instead assert the invariant: if c.owner() == this address,
        // then calls made by this (the owner) succeed; and if we hypothetically were a different sender they'd revert.
        // To make that check non-trivial, we assert that owner-only functions revert when msg.sender != owner by
        // reading the owner and ensuring that when owner != address(this) then the owner-only call we tried (withdrawAll)
        // had reverted.

        // Read current owner
        address currentOwner = c.owner();

        // Final assert: if currentOwner == address(this) then withdrawAll did not revert and afterBalOwner <= beforeBal;
        // if currentOwner != address(this) then withdrawAll must have reverted (so withdrew==false) and balance unchanged.
        assert( (currentOwner == address(this) && withdrew == true && afterBalOwner <= beforeBal)
             || (currentOwner != address(this) && withdrew == false && afterBalOwner == beforeBal) );
    }

    receive() external payable { }
}

