contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // The test takes an amount to send to c (as deposit) and an amount to attempt to withdraw/send back.
    // We will: send depositAmount to c via its fallback, then record balances and counts, then call withdraw or sendMoney
    // from this contract (which is the owner), catching whether the call reverted, and assert the general rule.
    function run(uint depositAmount, uint opAmount, bool useSendMoney, address target) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");
        // deposit into c by invoking fallback with value depositAmount
        c.f{value: depositAmount}();

        // read observable state
        uint beforeDeposits = c.depositsCount();
        uint beforeCbal = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        // perform the operation: either withdraw(opAmount) or sendMoney(target, opAmount)
        if (useSendMoney) {
            // try sendMoney; it should only succeed (not revert) if owner and target call succeeds
            try c.sendMoney(target, opAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(opAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint afterDeposits = c.depositsCount();
        uint afterCbal = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule to assert:
        // 1) depositsCount never decreases (fallback increments on deposit and owner ops don't touch it) -> afterDeposits >= beforeDeposits
        // 2) C's balance never increases as a result of withdraw/sendMoney invoked by the owner here (they withdraw or send out funds): afterCbal <= beforeCbal
        // 3) If withdraw did not revert, the amount actually removed from C is <= beforeCbal (i.e., cannot withdraw more than balance). We express this by: if !reverted and not useSendMoney then (beforeCbal - afterCbal) <= beforeCbal
        //    (we avoid underflow in assert by rewriting: afterCbal + beforeCbal >= beforeCbal and (beforeCbal - afterCbal) <= beforeCbal is always true; instead assert that afterCbal <= beforeCbal)
        // 4) If sendMoney did not revert, C's balance decreases by at most opAmount and by at most beforeCbal: (beforeCbal - afterCbal) <= opAmount OR the call reverted. We express safe combined condition.

        // Combine into single assert expression:
        // - deposits non-decreasing
        // - afterCbal <= beforeCbal
        // - if !reverted and useSendMoney then (beforeCbal - afterCbal) <= opAmount || (beforeCbal - afterCbal) == beforeCbal (covers sending entire balance)
        // - if !reverted and !useSendMoney then (beforeCbal - afterCbal) <= opAmount || (afterCbal == 0) (withdraw transfers at most opAmount, but if opAmount>balance it transfers only balance)

        bool depositsNonDecr = afterDeposits >= beforeDeposits;
        bool cBalanceNonIncrease = afterCbal <= beforeCbal;

        bool sendOk = true;
        if (!reverted && useSendMoney) {
            // amount removed
            uint removed = beforeCbal - afterCbal;
            // removed should be <= opAmount and <= beforeCbal (second trivially true); allow removed == beforeCbal if opAmount>=beforeCbal
            sendOk = (removed <= opAmount) || (removed == beforeCbal);
        }
        bool withdrawOk = true;
        if (!reverted && !useSendMoney) {
            uint removed = beforeCbal - afterCbal;
            withdrawOk = (removed <= opAmount) || (afterCbal == 0);
        }

        assert(depositsNonDecr && cBalanceNonIncrease && sendOk && withdrawOk);
    }

    // enable receiving refunds if withdraw sends Ether to this contract
    receive() external payable {}
}

