            require(address(this).balance >= depositAmount);
            (bool s, ) = address(c).call{value: depositAmount}("");
            s; // ignore
        }

        // read observable state before
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();
        address owner = c.owner();

        bool reverted;

        // Perform exactly one top-level state-changing call on c using try/catch
        if (action == 0) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (action == 1) {
            try c.withdraw(value) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.sendMoney(target, value) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read observable state after
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule:
        // - If this contract is the owner: the call must not increase depositsCount nor increase c's balance.
        // - If not the owner: the call must revert and leave depositsCount and c's balance unchanged.
        assert(
            (address(this) == owner && !reverted && afterDeposits >= beforeDeposits && afterBalance <= beforeBalance)
            ||
            (address(this) != owner && reverted && afterDeposits == beforeDeposits && afterBalance == beforeBalance)
        );
    }

    receive() external payable {}
}

